    22	#define RING_CAPACITY 4096u   /* power of two — the mask depends on it */
    23	#define RING_PAYLOAD    16u   /* bytes; a Mode 01 reply's data (<= 5 bytes) fits with room */
    24	
    25	/* One sample, as its producer decoded it; storaged turns it into a D-034 sample record. */
