    27	    uint64_t seq;                    /* set by ring_push: the slot's position, never reused */
    28	    uint64_t mono_ns;                /* CLOCK_MONOTONIC at capture */
    29	    uint8_t  mode;                   /* 0x01 for Mode 01; 0x00 for the box's own sensors (D-037) */
    30	    uint8_t  pid;
    31	    uint8_t  len;                    /* bytes of data[] in use */
    32	    uint8_t  src;                    /* data_src_t — live | replay | synth; 0 is refused */
    33	    float    value;                  /* the decoded value, in the PID's unit */
    34	    uint8_t  data[RING_PAYLOAD];     /* the reply's raw data bytes */
    35	} ring_slot_t;
    36	
    37	#define RING_LINE    64u          /* cache line on the Pi 4's Cortex-A72 */
    38	#define RING_MAGIC   0x474E5243u  /* the bytes "CRNG" */
    39	#define RING_VERSION 3u           /* bump whenever ring_t or ring_slot_t changes layout */
