    45	/* The header lets an attaching process refuse a ring written by a different build.
    46	 * head and tail each own a cache line, so the producer's stores never invalidate the
    47	 * line the consumer is spinning on, and the reverse. */
    48	typedef struct {
    49	    uint32_t magic;          /* RING_MAGIC */
    50	    uint16_t version;        /* RING_VERSION */
    51	    uint16_t slot_size;      /* sizeof(ring_slot_t) */
    52	    uint32_t capacity;       /* RING_CAPACITY */
