    54	    _Alignas(RING_LINE) _Atomic uint64_t head;      /* producer writes */
    55	    _Alignas(RING_LINE) _Atomic uint64_t tail;      /* consumer writes */
    56	    _Alignas(RING_LINE) _Atomic uint64_t overruns;  /* refused pushes — must stay zero */
