    21	void ring_init(ring_t *r)
    22	{
    23	    r->magic     = RING_MAGIC;
    24	    r->version   = RING_VERSION;
    25	    r->slot_size = (uint16_t)sizeof(ring_slot_t);
    26	    r->capacity  = RING_CAPACITY;
    27	    memset(r->slot, 0, sizeof r->slot);
    28	    atomic_init(&r->head, 0);
    29	    atomic_init(&r->tail, 0);
    30	    atomic_init(&r->overruns, 0);
    31	    atomic_init(&r->rejected, 0);
    32	}
