    40	bool ring_push(ring_t *r, const ring_slot_t *in)
    41	{
    42	    if (!SRC_IS_VALID(in->src)) {
    43	        /* An unlabeled slot would reach the log as data nobody vouched for (D-040). */
    44	        atomic_fetch_add_explicit(&r->rejected, 1, memory_order_relaxed);
    45	        return false;
    46	    }
    47	
    48	    uint64_t head = atomic_load_explicit(&r->head, memory_order_relaxed);
    49	    uint64_t tail = atomic_load_explicit(&r->tail, memory_order_acquire);
    50	
    51	    if (head - tail >= RING_CAPACITY) {
    52	        /* Full. Refuse rather than overwrite: an unread sample is data the diagnosis
    53	         * needs, and a silent overwrite is exactly the hidden loss DECISIONS B.3
    54	         * forbids. */
    55	        atomic_fetch_add_explicit(&r->overruns, 1, memory_order_relaxed);
    56	        return false;
    57	    }
    58	
    59	    /* The ring numbers its own slots. head lives with the ring, so the numbering stays
    60	     * continuous when a producer restarts, and a gap seen by the consumer is a real
    61	     * loss, never a producer that started again from zero. */
    62	    r->slot[head & MASK] = *in;
    63	    r->slot[head & MASK].seq = head;
    64	    atomic_store_explicit(&r->head, head + 1, memory_order_release);
    65	    return true;
    66	}
    67	
    68	bool ring_peek(const ring_t *r, size_t i, ring_slot_t *out)
    69	{
    70	    /* tail is ours (relaxed); head is the producer's, and acquire makes the slot it
    71	     * published visible before we copy it. */
    72	    uint64_t tail = atomic_load_explicit(&r->tail, memory_order_relaxed);
    73	    uint64_t head = atomic_load_explicit(&r->head, memory_order_acquire);
    74	
    75	    if (head - tail <= (uint64_t)i) return false;
    76	
    77	    *out = r->slot[(tail + i) & MASK];
    78	    return true;
    79	}
