    81	bool ring_release(ring_t *r, size_t n)
    82	{
    83	    uint64_t tail = atomic_load_explicit(&r->tail, memory_order_relaxed);
    84	    uint64_t head = atomic_load_explicit(&r->head, memory_order_acquire);
    85	
    86	    if ((uint64_t)n > head - tail) return false;
    87	
    88	    /* release: our reads of these slots finish before the producer may reuse them. */
    89	    atomic_store_explicit(&r->tail, tail + n, memory_order_release);
