   159	    CHECK(!ring_push(r, &s), "an unlabeled slot must be refused (D-040)");
   160	    CHECK(ring_rejected(r) == 1, "the refusal must be counted");
   161	    CHECK(ring_overruns(r) == 0, "a rejection is not an overrun");
   162	    CHECK(ring_depth(r) == 0, "nothing was queued");
   163	
   164	    s.src = SRC_SYNTH + 1;
   165	    CHECK(!ring_push(r, &s), "an out-of-range label must be refused");
   166	    free(r);
   167	}
