   169	static void test_ring_numbers_its_slots(void)
   170	{
   171	    ring_t *r = aligned_alloc(RING_LINE, sizeof *r);   /* ring_t is cache-line aligned */
   172	    if (r == NULL) { failures++; return; }
   173	    ring_init(r);
   174	
   175	    ring_slot_t s = mk(12345), out;   /* whatever seq the producer sets is replaced */
   176	    CHECK(ring_push(r, &s) && ring_push(r, &s), "two pushes");
   177	    CHECK(ring_pop(r, &out) && out.seq == 0, "first slot is seq 0");
   178	    CHECK(ring_pop(r, &out) && out.seq == 1, "second slot is seq 1");
   179	    free(r);
   180	}
