   182	/* storaged's pattern (D-039): look at a batch, write it, fsync, and only then free it.
   183	 * Until the release, the slots stay put and the producer cannot reuse them. */
   184	static void test_peek_then_release(void)
   185	{
   186	    ring_t *r = aligned_alloc(RING_LINE, sizeof *r);   /* ring_t is cache-line aligned */
   187	    if (r == NULL) { failures++; return; }
   188	    ring_init(r);
   189	
   190	    for (uint64_t i = 0; i < 5; i++) {
   191	        ring_slot_t s = mk(i);
   192	        CHECK(ring_push(r, &s), "push");
   193	    }
   194	
   195	    ring_slot_t out;
   196	    CHECK(ring_peek(r, 0, &out) && out.seq == 0, "peek oldest");
   197	    CHECK(ring_peek(r, 4, &out) && out.seq == 4, "peek newest");
   198	    CHECK(!ring_peek(r, 5, &out), "peek past the newest");
   199	    CHECK(ring_depth(r) == 5, "peeking consumes nothing");
   200	
   201	    CHECK(!ring_release(r, 6), "release more than is unread");
   202	    CHECK(ring_depth(r) == 5, "a refused release consumes nothing");
   203	    CHECK(ring_release(r, 3), "release a batch of three");
   204	    CHECK(ring_depth(r) == 2, "depth after release");
   205	    CHECK(ring_peek(r, 0, &out) && out.seq == 3, "next unread after release");
   206	
   207	    /* A full ring whose slots are peeked but not released still refuses the producer. */
   208	    for (uint64_t i = 0; ring_depth(r) < RING_CAPACITY; i++) {
   209	        ring_slot_t s = mk(i);
   210	        CHECK(ring_push(r, &s), "fill");
   211	    }
   212	    ring_slot_t extra = mk(0);
   213	    CHECK(ring_peek(r, 0, &out), "peek on full ring");
   214	    CHECK(!ring_push(r, &extra), "peeked but unreleased slots must not be overwritten");
   215	    free(r);
   216	}
