   218	int main(void)
   219	{
   220	    test_peek_then_release();
   221	    test_ring_numbers_its_slots();
   222	    test_unlabeled_slot_is_refused();
   223	    test_concurrent_order_and_depth();
   224	    test_empty_then_fifo();
   225	    test_full_refuses_never_overwrites();
   226	    test_wraparound();
   227	    return failures == 0 ? 0 : 1;
